mapper.select:
select t.region_code,t.region_code regionCode,t.pa_id,t.pa_id paId,t.pr_id,t.pr_id
prId,t.remark,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id communityId,
t.create_time createTime,pa.num paNum
from parking_region t
left join parking_area pa on t.pa_id = pa.pa_id and pa.community_id = t.community_id
where 1 =1

    and t.region_code= #{regionCode}


    and t.pa_id= #{paId}


    and t.pr_id= #{prId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update parking_region t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.region_code= #{regionCode}


    , t.pa_id= #{paId}


    , t.remark= #{remark}


    , t.community_id= #{communityId}

where 1=1

    and t.pr_id= #{prId}

